let pendingUndo=null;const undoDrafts=new Map();
function reviewHistory(){return reviewState.events.map(e=>{const n=index.get(e.entityId),p=DATA.properties.find(p=>p.key===e.field),c=e.correction;return `<li><div class="history-title"><strong>${esc(n?label(n):e.entityId||'')} · ${esc(p?.labels?.[lang]||e.field||'')}</strong><span>${rt(e.action==='undo'?'undone':e.action==='approve'?'approved':'rejected')}</span></div><small>${esc(e.created_at)}</small><p>${esc(e.note)}</p>${e.action==='approve'?(c?.reverted?`<span>${rt('undone')}</span>`:c?.canUndo?`<button data-undo="${e.id}" ${!reviewState.canReview||reviewBusy||opBusy?'disabled':''}>${rt('undo')}</button>`:`<small>${rt('unavailable')}</small>`):''}</li>`}).join('')||`<li>${rt('nohistory')}</li>`}
function undoTarget(id){return reviewState.events.find(e=>e.id===id)?.correction||reviewState.candidates.find(c=>c.correction?.eventId===id)?.correction}
function undoConfirmation(){if(!pendingUndo)return '';const c=undoTarget(pendingUndo);if(!c)return `<section class="undo-confirm"><p>${rt('conflict')}</p><button id="undo-cancel">${rt('cancel')}</button></section>`;const n=index.get(c.entityId),p=DATA.properties.find(p=>p.key===c.field);return `<section class="undo-confirm" role="region" aria-labelledby="undo-title"><h3 id="undo-title">${rt('undo')} · ${esc(n?label(n):c.entityId)} · ${esc(p?.labels?.[lang]||c.field)}</h3><p>${rt('undoHint')}</p><div class="candidate-diff"><div><small>${rt('current')}</small><p>${esc(JSON.stringify(c.fromValue))}</p></div><div><small>${rt('restore')}</small><p>${esc(JSON.stringify(c.toValue))}</p></div></div>${!c.canUndo?`<p>${rt('conflict')}</p>`:''}<label for="undo-note">${rt('undoReason')}</label><textarea id="undo-note" maxlength="500">${esc(undoDrafts.get(pendingUndo)||'')}</textarea><div class="review-actions"><button id="undo-confirm" ${!c.canUndo||!reviewState.canReview||reviewBusy||opBusy?'disabled':''}>${rt('confirmUndo')}</button><button id="undo-cancel" ${reviewBusy?'disabled':''}>${rt('cancel')}</button></div></section>`}
async function submitUndo(){const c=undoTarget(pendingUndo);if(!c||reviewBusy)return;const note=undoDrafts.get(pendingUndo)||'';if(!note.trim()){reviewMessage=rt('undoReason');renderReview();$('#undo-note')?.focus();return}const eventId=pendingUndo;if(await reviewRequest('/api/review/undo/'+eventId,{expectedVersion:c.expectedVersion,note})){pendingUndo=null;undoDrafts.delete(eventId);renderReview()}}
const rt=k=>REVIEW[lang][k];
const NAV={zh:{back:'返回上一条目',browse:'沿关系探索',people:'参与人物',records:'唱片与版本',songs:'歌曲、作品与录音',tracks:'已关联的曲目位置',other:'其他关系',role:'按署名筛选',all:'全部署名',on:'收录版本',contains:'收录条目',hasEdition:'发行版本',songEntry:'歌曲入口',trackSlot:'对应曲目位置'},en:{back:'Previous entry',browse:'Explore connections',people:'People & credits',records:'Records & editions',songs:'Songs, works & recordings',tracks:'Linked track slots',other:'Other connections',role:'Filter by credit',all:'All credits',on:'Edition',contains:'Contains entry',hasEdition:'Release edition',songEntry:'Song entry',trackSlot:'Corresponding track slot'},ja:{back:'前の項目に戻る',browse:'つながりをたどる',people:'人物・クレジット',records:'レコード・発売版',songs:'楽曲・作品・録音',tracks:'関連する収録位置',other:'その他の関係',role:'クレジットで絞り込み',all:'すべてのクレジット',on:'収録版',contains:'収録項目',hasEdition:'発売版',songEntry:'楽曲の項目',trackSlot:'対応する収録位置'}};
const nt=k=>NAV[lang][k];
let detailHistory=[],creditFilter='';
const detailGroups=new Map();
function relationText(e,n){
 const inverse=e.target===n.id;
 const key=inverse?({track_on:'contains',edition_of:'hasEdition',represents_work:'songEntry',corresponds_to:'trackSlot'})[e.type]:null;
 return (key?nt(key):t(e.type))+(e.attributes?.role?' · '+localValue(e.attributes.role):'')+(e.attributes?.creditedAs?' · '+localValue(e.attributes.creditedAs):'');
}
function connectionRows(n){
 const rows=new Map();
 for(const e of edges.filter(e=>e.source===n.id||e.target===n.id)){
  const other=index.get(e.source===n.id?e.target:e.source);if(!other)continue;
  // The model section already exposes these ordered/edition relationships.
  if(n.type==='edition'&&other.type==='track'&&other.editionId===n.id)continue;
  if(n.type==='album'&&other.type==='edition'&&other.albumId===n.id)continue;
  if(!rows.has(other.id))rows.set(other.id,{node:other,edges:[]});rows.get(other.id).edges.push(e);
 }
 return [...rows.values()];
}
function connectionsSection(n){
 const rows=connectionRows(n),isPerson=['person','artist'].includes(n.type);
 const roles=[...new Set(rows.flatMap(r=>r.edges.map(e=>e.type)).filter(k=>['released','performer','composer','lyricist','arranger','produced','co_produced','musician','member_of'].includes(k)))];
 const filters=isPerson&&roles.length>1?`<label class="credit-filter">${nt('role')}<select id="credit-filter"><option value="">${nt('all')}</option>${roles.map(k=>`<option value="${k}" ${creditFilter===k?'selected':''}>${t(k)}</option>`).join('')}</select></label>`:'';
 const groups={people:[],records:[],songs:[],tracks:[],other:[]};
 for(const row of rows){if(creditFilter&&!row.edges.some(e=>e.type===creditFilter))continue;const ty=row.node.type;groups[['artist','person'].includes(ty)?'people':['album','edition'].includes(ty)?'records':['song','work','recording'].includes(ty)?'songs':ty==='track'?'tracks':'other'].push(row)}
 return `<section class="connection-browser" aria-label="${nt('browse')}"><h3>${nt('browse')}</h3>${filters}`+Object.entries(groups).filter(([,rows])=>rows.length).map(([key,rows])=>{
  const groupKey=n.id+':'+key,open=detailGroups.has(groupKey)?detailGroups.get(groupKey):key!=='tracks';
  return `<details class="connection-group" data-connection-group="${groupKey}" ${open?'open':''}><summary>${nt(key)} · ${rows.length}</summary>`+rows.map(row=>{
   const other=row.node,edition=other.type==='track'?index.get(other.editionId):null;
   return `<button class="relation connection-entry" data-related="${other.id}"><span><strong>${esc(label(other))}</strong><small>${esc(t(other.type))}${other.year?' · '+other.year:''}</small>${edition?`<small class="edition-context">${nt('on')}: ${esc(label(edition))}</small>`:''}<small class="credit-roles">${[...new Set(row.edges.map(e=>relationText(e,n)))].map(esc).join(' · ')}</small></span></button>`
  }).join('')+'</details>'
 }).join('')+'</section>';
}
function backToEntry(){const previous=detailHistory.pop();if(!previous)return;select(previous.id,{remember:false});creditFilter=previous.creditFilter;renderDetail();$('.detail-shell').scrollTop=previous.scrollTop;const target=$$('#detail [data-related]').find(b=>b.dataset.related===previous.focusId);(target||$('#detail h2'))?.focus({preventScroll:true})}
function modelSection(n){let html='';if(n.type==='album'){const editions=nodes.filter(x=>x.type==='edition'&&x.albumId===n.id);if(editions.length)html+=`<h3>${rt('editions')} · ${editions.length}</h3>`+editions.map(e=>`<button class="relation" data-related="${e.id}"><span>${esc(e.attributes.releaseDate?.value||'')} · ${esc(e.attributes.catalogNumber?.value||'')}</span><small>${esc(e.attributes.format?.value||'')}</small></button>`).join('')}
 if(n.type==='edition'){const tracks=nodes.filter(x=>x.type==='track'&&x.editionId===n.id).sort((a,b)=>a.position-b.position);html+=`<h3>${rt('tracks')} · ${tracks.length}</h3><ol class="edition-tracks">`+tracks.map(x=>`<li><button data-related="${x.id}">${esc(label(x))}${x.attributes?.trackKind?`<small class="track-kind">${esc(localValue(x.attributes.trackKind.value))}</small>`:''}</button></li>`).join('')+'</ol>'}
 if(n.reviewNotes?.length)html+=`<div class="source-conflict"><strong>${rt('conflicts')}</strong>`+n.reviewNotes.map(note=>`<p>${esc(note.message)}</p>`).join('')+'</div>';
 return html;
}
const INTAKE={zh:{title:'导入前预览',hint:'先检查来源与字段差异，再加入待审核队列。重复项和当前值相同的项会跳过；任一无效项会阻止整批导入。不会自动批准。',new:'新候选',existing:'已有候选',unchanged:'与当前值相同',duplicate_batch:'批内重复',invalid:'无效',confirm:'加入待审核队列',cancel:'取消导入',loading:'正在检查候选…',row:'第',source:'来源',date:'采集日期',done:'导入完成',inserted:'新增',skipped:'跳过'},en:{title:'Preview candidate import',hint:'Check sources and field differences before adding to review. Duplicates and unchanged values are skipped; any invalid row blocks the whole batch. Nothing is approved automatically.',new:'New candidate',existing:'Already in review',unchanged:'Matches current value',duplicate_batch:'Duplicate in batch',invalid:'Invalid',confirm:'Add to pending review',cancel:'Cancel import',loading:'Checking candidates…',row:'Row',source:'Source',date:'Checked on',done:'Import complete',inserted:'Added',skipped:'Skipped'},ja:{title:'読み込み前の確認',hint:'出典と項目の差分を確認してからレビューに追加します。重複と同じ値はスキップし、無効な行がある場合は全件の読み込みを停止します。自動承認はしません。',new:'新しい候補',existing:'既存の候補',unchanged:'現在値と同じ',duplicate_batch:'バッチ内の重複',invalid:'無効',confirm:'未確認キューに追加',cancel:'読み込みを中止',loading:'候補を確認中…',row:'行',source:'出典',date:'確認日',done:'読み込み完了',inserted:'追加',skipped:'スキップ'}};
const it=k=>INTAKE[lang][k]||k;
let intake=null,intakeInput=null,intakeLoading=false,intakeEpoch=0;
function intakePanel(){if(!intake&&!intakeLoading)return '';return `<section class="intake-panel" aria-labelledby="intake-title"><h3 id="intake-title" tabindex="-1">${it('title')}</h3><p>${it('hint')}</p>${intakeLoading?`<p role="status">${it('loading')}</p>`:`<div class="intake-counts">${Object.entries(intake.counts).map(([k,v])=>`<span>${it(k)}: ${v}</span>`).join('')}</div><ol class="intake-rows">${intake.rows.map(r=>{const c=r.candidate,n=c&&index.get(c.entityId),p=c&&DATA.properties.find(p=>p.key===c.field);return `<li><strong>${it('row')} ${r.row} · ${it(r.disposition)}${r.existingStatus?' · '+rt(r.existingStatus):''}${r.duplicateOf?' → '+r.duplicateOf:''}</strong>${c?`<h4>${esc(n?label(n):c.entityId)} · ${esc(p?.labels?.[lang]||c.field)}</h4><div class="candidate-diff"><div><small>${rt('current')}</small><p>${esc(JSON.stringify(r.currentValue))}</p></div><div><small>${rt('proposed')}</small><p>${esc(JSON.stringify(c.value))}</p></div></div><a href="${esc(validURL(c.sourceUrl)||'#')}" target="_blank" rel="noopener noreferrer">${it('source')} · ${esc(c.sourceType)}</a><p class="intake-url">${esc(c.sourceUrl)}</p><small>${it('date')}: ${esc(c.checkedAt)}</small><p>${esc(c.note)}</p>`:`<p>${esc(r.error)}</p>`}</li>`}).join('')}</ol>`}<div class="review-actions">${!intakeLoading?`<button id="intake-confirm" ${!intake.valid||!intake.counts.new||!reviewState.canReview||reviewBusy||opBusy?'disabled':''}>${it('confirm')}</button>`:''}<button id="intake-cancel" ${reviewBusy?'disabled':''}>${it('cancel')}</button></div></section>`}
async function previewFile(file){if(reviewBusy||!file)return;const epoch=++intakeEpoch;intake=null;intakeInput=null;intakeLoading=true;reviewMessage='';renderReview();try{if(file.size>65536)throw Error('body_too_large');const parsed=JSON.parse(await file.text());if(epoch!==intakeEpoch)return;const body={candidates:Array.isArray(parsed)?parsed:parsed?.candidates};const encoded=JSON.stringify(body);if(new TextEncoder().encode(encoded).length>65536)throw Error('body_too_large');const response=await fetch('/api/review/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:encoded});const result=await response.json();if(epoch!==intakeEpoch)return;if(!response.ok)throw Error(result.error||'error');intake=result;intakeInput=body}catch(e){if(epoch===intakeEpoch)reviewMessage=rt('error')+' · '+e.message}finally{if(epoch===intakeEpoch){intakeLoading=false;renderReview();$('#intake-title')?.focus()}}}
async function confirmIntake(){if(!intake?.valid||!intake.counts.new||reviewBusy||opBusy||!reviewState.canReview)return;const body=intakeInput;if(await reviewRequest('/api/review/import',body)){intake=null;intakeInput=null;renderReview()}}

const reviewDrafts=new Map();
let reviewState=null,reviewFilter='pending',reviewMessage='',reviewBusy=false,reviewLoading=false;
async function refreshArchive(){const r=await fetch('/api/graph',{cache:'no-store'});if(!r.ok)throw Error('refresh');const fresh=await r.json();if(!Array.isArray(fresh.nodes)||!Array.isArray(fresh.edges))throw Error('refresh');nodes.splice(0,nodes.length,...fresh.nodes);edges.splice(0,edges.length,...fresh.edges);index.clear();for(const n of nodes)index.set(n.id,n);DATA.properties=fresh.properties||DATA.properties;DATA.entityAliases=fresh.entityAliases||{};DATA.revision=fresh.revision;DATA.updatedAt=fresh.updatedAt;degrees.clear();cloudPoints.clear();nodes.forEach((n,i)=>{degrees.set(n.id,edges.filter(e=>e.source===n.id||e.target===n.id).length);const y=1-2*(i+.5)/nodes.length,angle=i*2.399963229728653,rad=Math.sqrt(1-y*y),depth=.6+.4*((i*37%101)/100);cloudPoints.set(n.id,{x:Math.cos(angle)*rad*depth,y:y*depth,z:Math.sin(angle)*rad*depth})});if(selected&&!index.has(selected))selected=DATA.entityAliases[selected]||null;detailHistory=detailHistory.filter(h=>index.has(h.id));}

async function loadReview(){if(reviewLoading)return false;reviewLoading=true;let ok=false;try{const r=await fetch('/api/review',{cache:'no-store'});if(!r.ok)throw Error();const next=await r.json();await refreshArchive();reviewState=next;ok=true}catch{reviewMessage=rt('error')}finally{reviewLoading=false;if(view==='review')renderReview()}return ok}

function renderReview(){const el=$('#review');if(!reviewState){el.innerHTML=`<h2>${rt('title')}</h2><p>${reviewLoading?rt('loading'):esc(reviewMessage||rt('loading'))}</p><button id="review-retry">${rt('refresh')}</button>`;$('#review-retry').onclick=loadReview;if(!reviewLoading&&!reviewMessage)loadReview();return}
 const list=reviewState.candidates.filter(c=>reviewFilter==='all'||c.status===reviewFilter);
 el.innerHTML=`<div class="review-header"><div><h2>${rt('title')}</h2><p>${rt('intro')}</p></div><button id="review-refresh">${rt('refresh')}</button></div><div class="review-controls">${['pending','approved','rejected','all'].map(k=>`<button data-review-filter="${k}" aria-pressed="${reviewFilter===k}">${rt(k)} ${k==='all'?reviewState.candidates.length:reviewState.candidates.filter(c=>c.status===k).length}</button>`).join('')}<label class="candidate-upload">${rt('import')}<input id="candidate-upload" type="file" accept="application/json,.json" ${!reviewState.canReview||reviewBusy||opBusy||intakeLoading?'disabled':''}></label></div><p class="meta-note">${rt('uploadHint')}</p>${!reviewState.canReview?`<p class="source-conflict">${rt('readonly')}</p>`:''}<p class="review-message" role="status">${esc(reviewMessage)}</p>${intakePanel()}<div class="review-list">${list.map(c=>{const n=index.get(c.entityId),p=DATA.properties.find(p=>p.key===c.field);return `<article class="review-card"><div class="review-card-heading"><h3>${esc(n?label(n):c.entityId)} · ${esc(p?.labels?.[lang]||c.field)}</h3><span>${rt(c.status)}</span></div><div class="candidate-diff"><div><small>${rt('current')}</small><p>${esc(JSON.stringify(c.currentValue))}</p></div><div><small>${rt('proposed')}</small><p>${esc(JSON.stringify(c.value))}</p></div></div><p>${esc(c.note||'')}</p><a class="source-link" href="${esc(validURL(c.sourceUrl)||'#')}" target="_blank" rel="noopener noreferrer">${rt('source')} · ${esc(c.sourceType)} · ${esc(c.checkedAt)}</a>${c.status==='pending'?`<textarea id="review-note-${esc(c.id)}" name="review-note-${esc(c.id)}" data-review-note="${c.id}" maxlength="500" aria-label="${rt('reason')}" placeholder="${rt('reason')}">${esc(reviewDrafts.get(c.id)||'')}</textarea><div class="review-actions"><button data-decision="approve" data-candidate="${c.id}" ${!reviewState.canReview||reviewBusy||opBusy?'disabled':''}>${rt('approve')}</button><button data-decision="reject" data-candidate="${c.id}" ${!reviewState.canReview||reviewBusy||opBusy?'disabled':''}>${rt('reject')}</button></div>`:c.status==='approved'&&c.correction?.canUndo?`<button data-undo="${c.correction.eventId}" ${!reviewState.canReview||reviewBusy||opBusy?'disabled':''}>${rt('undo')}</button>`:''}</article>`}).join('')||`<p>${rt('empty')}</p>`}</div><h3>${rt('history')}</h3><ul class="review-history">${reviewHistory()}</ul>${undoConfirmation()}`;
 $('#review-refresh').onclick=()=>{reviewMessage='';loadReview()};$$('[data-review-filter]').forEach(b=>b.onclick=()=>{reviewFilter=b.dataset.reviewFilter;renderReview()});
 $$('[data-review-note]').forEach(x=>x.oninput=()=>reviewDrafts.set(x.dataset.reviewNote,x.value));
 $$('[data-decision]').forEach(b=>b.onclick=()=>submitReview(b.dataset.candidate,b.dataset.decision));
 $$('[data-undo]').forEach(b=>b.onclick=()=>{pendingUndo=b.dataset.undo;renderReview();$('#undo-note')?.focus()});
 if($('#undo-cancel'))$('#undo-cancel').onclick=()=>{const id=pendingUndo;pendingUndo=null;renderReview();$$('[data-undo]').find(b=>b.dataset.undo===id)?.focus()};
 if($('#undo-note'))$('#undo-note').oninput=e=>undoDrafts.set(pendingUndo,e.target.value);
 if($('#undo-confirm'))$('#undo-confirm').onclick=submitUndo;
 $('#candidate-upload').onchange=event=>previewFile(event.target.files?.[0]);
 if($('#intake-cancel'))$('#intake-cancel').onclick=()=>{intakeEpoch++;intake=null;intakeInput=null;intakeLoading=false;renderReview();$('#candidate-upload')?.focus()};
 if($('#intake-confirm'))$('#intake-confirm').onclick=confirmIntake;
 renderOperations(el);
}
async function reviewRequest(url,body){if(reviewBusy||opBusy)return false;reviewBusy=true;let committed=false;renderReview();try{const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await response.json();if(!response.ok)throw Error(response.status===409?'conflict':result.error||'error');committed=true;reviewMessage=url==='/api/review/import'?`${it('done')} · ${it('inserted')}: ${result.inserted} · ${it('skipped')}: ${result.skipped}`:rt('saved');if(!await loadReview())throw Error('refresh')}catch(e){reviewMessage=committed?rt('refreshNeeded'):(e.message==='conflict'?rt('conflict'):rt('error'))+' · '+e.message}finally{reviewBusy=false;renderReview()}return committed}

function submitReview(id,decision){const c=reviewState.candidates.find(c=>c.id===id);const note=$(`[data-review-note="${id}"]`).value;if(decision==='reject'&&!note.trim()){reviewMessage=rt('reason');renderReview();return}return reviewRequest('/api/review/'+id,{decision,expectedVersion:c.version,note})}

const BROWSE={zh:{all:'所有条目',albums:'唱片',people:'人物',songs:'歌曲',media:'媒体筛选',any:'全部资料',portraits:'有人物照片',players:'有唱片播放器',spotify:'有 Spotify 链接',youtube:'有 YouTube 视频',sort:'排序',featured:'图片与音乐优先',title:'按名称',oldest:'发行年：从早到晚',newest:'发行年：从晚到早',more:'显示更多',shown:'已显示',back:'返回音乐档案',relatedArtist:'关联人物',details:'查看详情',none:'此筛选暂无资料',reset:'重置档案筛选'},en:{all:'All entries',albums:'Records',people:'People',songs:'Songs',media:'Media filter',any:'All material',portraits:'With portraits',players:'With album players',spotify:'With Spotify links',youtube:'With YouTube videos',sort:'Sort',featured:'Images & music first',title:'By name',oldest:'Release year: oldest',newest:'Release year: newest',more:'Show more',shown:'Showing',back:'Back to the archive',relatedArtist:'Related people',details:'View details',none:'No entries match these filters',reset:'Reset archive filters'},ja:{all:'すべての項目',albums:'レコード',people:'人物',songs:'楽曲',media:'メディア絞り込み',any:'すべての資料',portraits:'人物写真あり',players:'アルバムプレーヤーあり',spotify:'Spotifyリンクあり',youtube:'YouTube動画あり',sort:'並び順',featured:'画像・音楽を優先',title:'名前順',oldest:'発売年：古い順',newest:'発売年：新しい順',more:'さらに表示',shown:'表示中',back:'アーカイブに戻る',relatedArtist:'関連人物',details:'詳細を見る',none:'条件に合う資料はありません',reset:'絞り込みをリセット'}};
const bt=k=>BROWSE[lang][k];
let catalogGroup='albums',mediaFilter='',catalogSort='featured',catalogLimit=24,catalogReturn=null;
function relatedPeople(n){const ids=edges.filter(e=>e.target===n.id||e.source===n.id).map(e=>e.source===n.id?e.target:e.source);return [...new Set(ids)].map(id=>index.get(id)).filter(x=>x&&['artist','person'].includes(x.type))}
function catalogList(){let list=filtered().filter(n=>catalogGroup==='all'||(catalogGroup==='albums'?n.type==='album':catalogGroup==='people'?['artist','person'].includes(n.type):n.type==='song'));list=list.filter(n=>!mediaFilter||(mediaFilter==='portraits'?!!portrait(n):mediaFilter==='players'?!!albumLink(n):verifiedLinks(n).some(l=>l.service===mediaFilter)));return list.sort((a,b)=>{let order=0;if(catalogSort==='featured')order=Number(!!(portrait(b)||albumLink(b)))-Number(!!(portrait(a)||albumLink(a)))||verifiedLinks(b).length-verifiedLinks(a).length;if(catalogSort==='oldest'||catalogSort==='newest'){if(!a.year||!b.year)order=Number(!a.year)-Number(!b.year);else order=catalogSort==='oldest'?a.year-b.year:b.year-a.year}return order||label(a).localeCompare(label(b),{zh:'zh-CN',en:'en',ja:'ja'}[lang])})}
function catalogCard(n){return `<article class="card" data-entry="${n.id}">${photo(n)}${player(n)}<button class="card-open" data-id="${n.id}"><small>${t(n.type)}${n.year?' / '+n.year:''}</small><h3>${esc(label(n))}</h3><p>${esc(n.labels?.ja===label(n)?n.labels?.en||'':n.labels?.ja||'')}</p>${relatedPeople(n).length?`<p class="card-people">${esc(relatedPeople(n).map(label).join(' · '))}</p>`:''}<span class="card-action">${bt('details')}</span></button><div class="card-links">${verifiedLinks(n).map(l=>`<a href="${esc(serviceURL(l))}" target="_blank" rel="noopener noreferrer" title="${esc(linkVersion(l)||linkType(l))}">${l.service==='spotify'?'Spotify':'YouTube'}<span>${esc(linkVersion(l)||linkType(l))}</span></a>`).join('')}</div></article>`}
function renderCatalog(){const list=catalogList();$('#catalog-controls').innerHTML=`<div class="catalog-groups" aria-label="${bt('all')}">${['albums','people','songs','all'].map(k=>`<button data-group="${k}" aria-pressed="${catalogGroup===k}">${bt(k)}</button>`).join('')}</div><div class="catalog-selects"><label>${bt('media')}<select id="media-filter">${['','portraits','players','spotify','youtube'].map(k=>`<option value="${k}">${bt(k||'any')}</option>`).join('')}</select></label><label>${bt('sort')}<select id="catalog-sort">${['featured','title','oldest','newest'].map(k=>`<option value="${k}">${bt(k)}</option>`).join('')}</select></label></div>`;
$('#media-filter').value=mediaFilter;$('#catalog-sort').value=catalogSort;$('#catalog-count').textContent=`${list.length} ${t('nodes')}`;
$('#cards').innerHTML=list.slice(0,catalogLimit).map(catalogCard).join('')||`<div class="catalog-empty"><p>${bt('none')}</p><button id="reset-catalog">${bt('reset')}</button></div>`;
renderCatalogMore(list);
$$('[data-group]').forEach(b=>b.onclick=()=>{catalogGroup=b.dataset.group;type='';catalogLimit=24;render();$$('[data-group]').find(x=>x.dataset.group===catalogGroup)?.focus()});$('#media-filter').onchange=e=>{mediaFilter=e.target.value;catalogLimit=24;render();$('#media-filter').focus()};$('#catalog-sort').onchange=e=>{catalogSort=e.target.value;catalogLimit=24;render();$('#catalog-sort').focus()};if($('#reset-catalog'))$('#reset-catalog').onclick=()=>{query=type=decade=mediaFilter='';catalogGroup='albums';catalogLimit=24;$('#search').value='';render()};}
function renderCatalogMore(list){$('#catalog-more').innerHTML=`<span>${bt('shown')} ${Math.min(catalogLimit,list.length)} / ${list.length}</span>${list.length>catalogLimit?`<button id="more-cards">${bt('more')}</button>`:''}`;if($('#more-cards'))$('#more-cards').onclick=()=>{const offset=catalogLimit;catalogLimit+=24;$('#cards').insertAdjacentHTML('beforeend',list.slice(offset,catalogLimit).map(catalogCard).join(''));$$('#cards [data-id]').forEach(b=>b.onclick=()=>select(b.dataset.id));bindImageErrors();renderCatalogMore(list);$$('#cards .card-open')[offset]?.focus()}}
function backToCatalog(){if(!catalogReturn)return;const saved=catalogReturn;({query,type,decade,catalogGroup,mediaFilter,catalogSort,catalogLimit}=saved);catalogReturn=null;detailHistory=[];creditFilter='';selected=null;view='catalog';document.body.classList.remove('detail-open');$('#search').value=query;render();requestAnimationFrame(()=>{const button=$$('#cards [data-id]').find(b=>b.dataset.id===saved.focusId);button?.focus({preventScroll:true});window.scrollTo({top:saved.scrollY||0,behavior:'instant'})})}

const VALUES={bass:['贝斯','ベース'],guitar:['吉他','ギター'],keyboards:['键盘','キーボード'],drums:['鼓','ドラム'],piano:['钢琴','ピアノ'],organ:['管风琴','オルガン'],synthesizer:['合成器','シンセサイザー'],voice:['人声','声'],musician:['音乐人','音楽家'],composer:['作曲家','作曲家'],arranger:['编曲家','編曲家'],singer:['歌手','歌手'],songwriter:['词曲作者','ソングライター'],'record producer':['音乐制作人','音楽プロデューサー'],keyboardist:['键盘手','キーボーディスト'],guitarist:['吉他手','ギタリスト'],bassist:['贝斯手','ベーシスト'],'bass guitar':['贝斯吉他','ベースギター'],'recording artist':['录音艺人','録音アーティスト'],'background vocal':['和声','バックボーカル'],Japan:['日本','日本'],Tokyo:['东京','東京'],Ikebukuro:['池袋','池袋'],Nakano:['中野','中野'],album:['专辑','アルバム'],day:['日','日'],year:['年','年']};
Object.assign(VALUES,{bonus_track:['附加曲','ボーナストラック'],'SACD (single-layer, 1 disc)':['单层SACD（1碟）','単層SACD（1枚）'],interlude:['间奏','間奏'],original_album_program:['原专辑曲目','オリジナル収録曲'],anniversary_bonus:['周年版附加曲','記念盤ボーナス曲'],remastered_reissue:['重制再版','リマスター再発'],anniversary_reissue:['周年纪念再版','周年記念再発'],original_album_scope:['原始专辑整体署名','オリジナル盤全体のクレジット'],'vinyl LP':['黑胶LP','アナログLP'],'limited production edition':['限定生产版','完全生産限定盤']});
VALUES.exact_release_track_link_reviewed_physical_master_unverified=['此发行版的录音目录关联已审核；实体母带仍未确认','この版の録音カタログ対応を確認。物理盤マスターは未確認'];
const localValue=x=>x==='exact_release_track_link_reviewed_physical_master_unverified'&&lang==='en'?'Exact release catalogue link reviewed; physical master unverified':lang==='en'?String(x):VALUES[x]?.[lang==='zh'?0:1]||String(x);

const serviceURL=l=>{try{const u=new URL(l.url);if(u.protocol!=='https:')return null;if(l.service==='spotify'&&u.hostname==='open.spotify.com'&&/^\/(album|track|artist)\/[A-Za-z0-9]{22}$/.test(u.pathname))return u.href;if(l.service==='youtube'&&((u.hostname==='www.youtube.com'||u.hostname==='youtube.com')&&u.pathname==='/watch'&&/^[\w-]{11}$/.test(u.searchParams.get('v')||'')))return u.href;return null}catch{return null}};
const linkVersion=l=>l.versionLabels?.[lang]||l.version||'';
const linkType=l=>({zh:{artist:'艺人主页',album:'专辑',track:'歌曲',official_music_video:'官方视频',official_audio:'官方音频',label_supplied_audio:'官方音频'},en:{artist:'Artist',album:'Album',track:'Track',official_music_video:'Official video',official_audio:'Official audio',label_supplied_audio:'Official audio'},ja:{artist:'アーティスト',album:'アルバム',track:'楽曲',official_music_video:'公式動画',official_audio:'公式音源',label_supplied_audio:'公式音源'}})[lang][l.resourceType]||l.resourceType||'';
const verifiedLinks=n=>(n.serviceLinks||[]).filter(l=>l.status==='verified'&&serviceURL(l));
const albumLink=n=>verifiedLinks(n).find(l=>l.service==='spotify'&&l.resourceType==='album');
const portrait=n=>(n.media||[]).find(m=>m.status==='verified'&&validURL(m.url));
function player(n){const l=albumLink(n);if(!l)return '';const id=new URL(l.url).pathname.split('/').pop();return `<div class="album-player"><iframe title="Spotify · ${esc(label(n))}" src="https://open.spotify.com/embed/album/${id}?utm_source=generator&theme=0" width="100%" height="152" loading="lazy" allow="encrypted-media; fullscreen; picture-in-picture" referrerpolicy="no-referrer"></iframe><small>${ux('cover')}${linkVersion(l)?' · '+esc(linkVersion(l)):''}</small></div>`}
function photo(n,detail=false){const m=portrait(n);if(!m)return '';return `<figure class="portrait ${detail?'portrait-detail':''}"><img src="${esc(validURL(m.url))}" alt="${esc(m.alt||label(n))}" loading="lazy" referrerpolicy="no-referrer"><figcaption><a href="${esc(validURL(m.sourcePage)||'#')}" target="_blank" rel="noopener noreferrer">${esc(m.creator)}</a> · <a href="${esc(validURL(m.licenseUrl)||'#')}" target="_blank" rel="noopener noreferrer">${esc(m.license)}</a> · ${esc(m.photoDate||'')}<details><summary>${ux('image')}</summary><p>${esc(m.attribution||'')}</p><p>${esc(m.changes||'')}</p></details></figcaption></figure>`}
function facts(n){return Object.entries(n.attributes||{}).map(([key,a])=>{const def=DATA.properties?.find(p=>p.key===key),name=def?.labels?.[lang]||key;let value=a.value??a;if(Array.isArray(value))value=value.map(localValue).join(' · ');if(value&&typeof value==='object')value=value[lang]||value.en||JSON.stringify(value);return `<div><dt>${esc(name)}</dt><dd>${esc(localValue(value))}${validURL(a.sourceUrl)?` <a class="evidence" href="${esc(a.sourceUrl)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(t('sources'))}">↗</a>`:''}</dd></div>`}).join('')}
function musicLinks(n){const links=verifiedLinks(n);return links.length?links.map(l=>`<a class="music-link ${l.service}" href="${esc(serviceURL(l))}" target="_blank" rel="noopener noreferrer"><strong>${l.service==='spotify'?'Spotify':'YouTube'}</strong><span>${esc(linkType(l))}${linkVersion(l)?' · '+esc(linkVersion(l)):''}</span></a>`).join(''):`<p class="meta-note">${ux('missing')}</p>`}
