// Structural review: drafts and preview are disposable, decisions persist server-side.
const OP={zh:{title:'实体、关系与录音身份审核',intro:'先查看来源和影响，再明确批准。相似名称只提供线索，不代表同一身份。新增实体先批准，依赖它的关系才可继续。',entity:'新增实体',relationship:'新增关系',recording_match:'录音匹配',merge:'合并重复实体',kind:'候选类型',draft:'建立候选',upload:'预览结构候选 JSON',preview:'预览',enqueue:'加入待审核队列',cancel:'取消',refresh:'刷新结构审核',sourceUrl:'来源 HTTPS URL',sourceType:'来源类型',checkedAt:'核查日期',note:'证据说明',id:'稳定实体 ID',type:'实体层级',labels:'名称',description:'简介',attributes:'带来源属性 JSON（可选）',externalIds:'外部标识 JSON（可选）',context:'版本与曲目字段 JSON（可选）',fromId:'要合并的重复实体',intoId:'保留的实体',same:'我已核对来源，确认是同一实体',source:'关系起点',target:'关系终点',relation:'关系类型',trackId:'特定曲目位置',editionId:'特定发行版本',recordingId:'录音实体',releaseId:'MusicBrainz 发行版 ID',matchBasis:'精确版本/曲目匹配依据',status:'审核状态',suggestions:'可能重复：仅供核查',same_external_id:'外部标识相同',same_normalized_name:'名称相似',impact:'受影响引用 / 关系',detail:'完整候选与来源',new:'新增',existing:'已有候选',duplicate_batch:'批内重复',blocked:'依赖未满足 / 冲突',invalid:'无效',confirm:'确认决定',reason:'审核理由（必填）',undo:'撤销结构变更',undoHint:'仅可撤销最后生效且资料未变化的结构批准。若有后续更改，先撤销后续操作。基础快照变更后不猜测恢复值。任何当前无法应用的批准均可安全移回待审核，其余已生效操作不受影响。',saved:'已保存；正式资料已刷新',error:'操作未完成，请保留草稿并刷新重试',empty:'暂无此类候选',history:'结构审核记录',conflicts:'已批准操作与当前资料冲突，请将无法应用的操作移回待审核，再核对其依赖',count:'项',stale:'内容已变化，请刷新后重新核对',pending:'待审核',approved:'已批准',rejected:'已拒绝',all:'全部',approve:'批准',reject:'拒绝'},en:{title:'Entity, relationship & recording review',intro:'Inspect evidence and impact before explicitly approving. Similar names are clues, not identity. Approve new entities before dependent relationships.',entity:'New entity',relationship:'New relationship',recording_match:'Recording match',merge:'Merge duplicate entities',kind:'Candidate type',draft:'Create candidate',upload:'Preview structural JSON',preview:'Preview',enqueue:'Add to pending queue',cancel:'Cancel',refresh:'Refresh structural review',sourceUrl:'Source HTTPS URL',sourceType:'Source type',checkedAt:'Checked date',note:'Evidence note',id:'Stable entity ID',type:'Entity layer',labels:'Name',description:'Description',attributes:'Sourced attributes JSON (optional)',externalIds:'External IDs JSON (optional)',context:'Edition / track fields JSON (optional)',fromId:'Duplicate entity to merge',intoId:'Entity to retain',same:'I checked the source and confirm the same identity',source:'Relationship source',target:'Relationship target',relation:'Relationship type',trackId:'Exact track slot',editionId:'Exact release edition',recordingId:'Recording entity',releaseId:'MusicBrainz release ID',matchBasis:'Exact edition / track matching evidence',status:'Review status',suggestions:'Possible duplicates: investigate only',same_external_id:'Same external identifier',same_normalized_name:'Similar normalized name',impact:'Affected references / relationships',detail:'Full candidate and evidence',new:'New',existing:'Existing candidate',duplicate_batch:'Duplicate in batch',blocked:'Dependency missing / conflict',invalid:'Invalid',confirm:'Confirm decision',reason:'Review reason (required)',undo:'Undo structural change',undoHint:'Only the latest effective structural approval can be reversed while its data is unchanged. Reverse later changes first. Any currently unapplied conflicting approval can be safely returned to pending; effective later operations are preserved. Seed updates never trigger a guessed inverse.',saved:'Saved; archive refreshed',error:'Could not complete. Keep the draft, refresh and retry.',empty:'No matching candidates',history:'Structural review history',conflicts:'Approved operations conflict with current data. Return unapplied conflicting operations to pending, then inspect their dependencies.',count:'items',stale:'Data changed. Refresh and inspect again.',pending:'Pending',approved:'Approved',rejected:'Rejected',all:'All',approve:'Approve',reject:'Reject'},ja:{title:'項目・関係・録音のレビュー',intro:'出典と影響を確認してから明示的に承認します。似た名前は候補であり、同一性の証明ではありません。新規項目を先に承認してから関係を追加します。',entity:'項目の追加',relationship:'関係の追加',recording_match:'録音の対応',merge:'重複項目を統合',kind:'候補の種類',draft:'候補を作成',upload:'構造候補JSONをプレビュー',preview:'プレビュー',enqueue:'未確認キューに追加',cancel:'キャンセル',refresh:'構造レビューを更新',sourceUrl:'出典 HTTPS URL',sourceType:'出典の種類',checkedAt:'確認日',note:'根拠の説明',id:'固定項目ID',type:'項目の階層',labels:'名前',description:'説明',attributes:'出典付き属性JSON（任意）',externalIds:'外部ID JSON（任意）',context:'発売版・収録位置JSON（任意）',fromId:'統合する重複項目',intoId:'残す項目',same:'出典を確認し、同一の項目と判断しました',source:'関係の起点',target:'関係の終点',relation:'関係の種類',trackId:'特定の収録位置',editionId:'特定の発売版',recordingId:'録音項目',releaseId:'MusicBrainz発売版ID',matchBasis:'発売版・収録位置の対応根拠',status:'レビュー状態',suggestions:'重複の可能性：要確認',same_external_id:'外部IDが一致',same_normalized_name:'名前が類似',impact:'影響する参照 / 関係',detail:'候補と出典の詳細',new:'新規',existing:'既存の候補',duplicate_batch:'バッチ内の重複',blocked:'依存項目が未承認 / 競合',invalid:'無効',confirm:'判断を確定',reason:'判断の理由（必須）',undo:'構造変更を取り消す',undoHint:'資料が変わっていない最新の構造承認のみ取り消せます。後続の変更を先に取り消してください。現在適用できない承認は未確認に戻せます。他の有効な操作を保持し、資料更新後の復元を推測しません。',saved:'保存し、資料を更新しました',error:'完了できません。下書きを保持し、更新して再試行してください。',empty:'該当する候補はありません',history:'構造レビュー履歴',conflicts:'承認済み操作と現資料が競合しています。適用できない操作を未確認に戻し、依存関係を再確認してください。',count:'件',stale:'資料が変わりました。更新して再確認してください。',pending:'未確認',approved:'承認済み',rejected:'却下済み',all:'すべて',approve:'承認',reject:'却下'}};
let opState=null,opLoading=false,opBusy=false,opMessage='',opFilter='pending',opKind='',opDraftKind='entity',opPreview=null,opInput=null,opPreparing=false,opEpoch=0,opDecision=null;const opDraft={},opNotes=new Map();
const ot=k=>OP[lang][k]||k;
const opInputField=(key,{area=false,list=false,type='text'}={})=>`<label>${esc(ot(key))}${area?`<textarea id="operation-input-${key}" name="${key}" data-op-input="${key}" maxlength="6000">${esc(opDraft[key]||'')}</textarea>`:`<input id="operation-input-${key}" name="${key}" data-op-input="${key}" type="${type}" ${list?'list="operation-entities"':''} value="${esc(opDraft[key]||'')}" maxlength="2000">`}</label>`;
function opForm(){const common=['sourceUrl','sourceType','checkedAt','note'];let fields='';if(opDraftKind==='entity'){fields=opInputField('id')+`<label>${ot('type')}<select id="operation-input-type" name="type" data-op-input="type">${Object.keys(colors).map(k=>`<option value="${k}" ${opDraft.type===k?'selected':''}>${t(k)}</option>`).join('')}</select></label>`+['zh','en','ja'].map(k=>`<label>${ot('labels')} · ${k}<input id="operation-input-labels_${k}" name="labels_${k}" data-op-input="labels_${k}" value="${esc(opDraft['labels_'+k]||'')}" maxlength="1000"></label><label>${ot('description')} · ${k}<textarea id="operation-input-description_${k}" name="description_${k}" data-op-input="description_${k}" maxlength="1000">${esc(opDraft['description_'+k]||'')}</textarea></label>`).join('')+['attributes','externalIds','context'].map(key=>opInputField(key,{area:true})).join('')}else if(opDraftKind==='relationship'){fields=['source','target'].map(k=>opInputField(k,{list:true})).join('')+`<label>${ot('relation')}<select id="operation-input-relation" name="relation" data-op-input="relation">${['arranger','co_produced','composer','corresponds_to','edition_of','lyricist','member_of','performer','produced','recording_entry_for','released','represents_work','track_on','recording_of'].map(k=>`<option value="${k}" ${opDraft.relation===k?'selected':''}>${t(k)}</option>`).join('')}</select></label>`+opInputField('attributes',{area:true})}else if(opDraftKind==='merge'){fields=['fromId','intoId'].map(k=>opInputField(k,{list:true})).join('')+`<label class="identity-check"><input type="checkbox" id="operation-input-same" name="same" data-op-input="same" ${opDraft.same?'checked':''}>${ot('same')}</label>`}else fields=['trackId','editionId','recordingId','releaseId'].map(k=>opInputField(k,{list:k!=='releaseId'})).join('')+opInputField('matchBasis',{area:true});return `<details class="operation-form" ${opDraft.open?'open':''}><summary>${ot('draft')}</summary><label>${ot('kind')}<select id="operation-draft-kind">${['entity','relationship','recording_match','merge'].map(k=>`<option value="${k}" ${opDraftKind===k?'selected':''}>${ot(k)}</option>`).join('')}</select></label><div class="operation-fields">${fields}${common.map(k=>opInputField(k,{area:k==='note',type:k==='checkedAt'?'date':'text'})).join('')}</div><button id="operation-draft-preview" ${!opState?.canReview||opBusy?'disabled':''}>${ot('preview')}</button></details>`}
function operationTitle(o){const name=id=>index.has(id)?label(index.get(id))+' · '+id:id;return o.kind==='entity'?o.node.labels[lang]+' · '+o.node.id:o.kind==='merge'?name(o.fromId)+' → '+name(o.intoId):o.kind==='recording_match'?name(o.trackId)+' → '+name(o.recordingId):name(o.relationship.source)+' → '+name(o.relationship.target)+' · '+t(o.relationship.type)}
function operationDetail(o){return `<details><summary>${ot('detail')}</summary><pre>${esc(JSON.stringify(o,null,2))}</pre></details><a class="source-link" href="${esc(validURL(o.sourceUrl)||'#')}" target="_blank" rel="noopener noreferrer">${esc(o.sourceType)} · ${esc(o.checkedAt)} · ${rt('source')}</a><p>${esc(o.note)}</p>`}
function opSuggestionList(rows){return rows?.length?`<p>${ot('suggestions')}</p><ul>${rows.map(r=>`<li>${esc(r.labels?.[lang]||r.id)} · ${esc(r.id)} · ${ot(r.reason)}</li>`).join('')}</ul>`:''}
function renderOperations(container){let el=container.querySelector('#operations');if(!el){el=document.createElement('section');el.id='operations';el.className='operations-panel';container.appendChild(el)}
 if(!opState){el.innerHTML=`<h2>${ot('title')}</h2><p role="status">${esc(opMessage||rt('loading'))}</p><button id="operation-refresh" ${opLoading?'disabled':''}>${ot('refresh')}</button>`;el.querySelector('button').onclick=loadOperations;if(!opLoading&&!opMessage)loadOperations();return}
 const rows=opState.operations.filter(r=>(opFilter==='all'||r.status===opFilter)&&(!opKind||r.operation.kind===opKind));
 el.innerHTML=`<h2>${ot('title')}</h2><p>${ot('intro')}</p><p>${ot('undoHint')}</p><div class="review-controls"><button id="operation-refresh" ${opBusy||opLoading?'disabled':''}>${ot('refresh')}</button><label>${ot('status')}<select id="operation-filter">${['pending','approved','rejected','all'].map(k=>`<option value="${k}" ${opFilter===k?'selected':''}>${ot(k)}</option>`).join('')}</select></label><label>${ot('kind')}<select id="operation-kind"><option value="">${ot('all')}</option>${['entity','relationship','recording_match','merge'].map(k=>`<option value="${k}" ${opKind===k?'selected':''}>${ot(k)}</option>`).join('')}</select></label><label class="candidate-upload">${ot('upload')}<input type="file" id="operation-upload" accept="application/json,.json" ${!opState.canReview||opBusy||reviewBusy?'disabled':''}></label></div><datalist id="operation-entities">${nodes.map(n=>`<option value="${esc(n.id)}">${esc(label(n))} · ${t(n.type)}</option>`).join('')}</datalist>${opForm()}<p role="status" class="review-message">${esc(opMessage)}</p>${opState.conflicts?.length?`<p class="source-conflict">${ot('conflicts')}</p><pre>${esc(JSON.stringify(opState.conflicts,null,2))}</pre>`:''}${opPreparing?`<button id="operation-preview-cancel">${ot('cancel')}</button>`:''}${opPreview?`<section class="operation-preview"><h3 tabindex="-1" id="operation-preview-title">${ot('preview')} · ${opPreview.rows.length} ${ot('count')}</h3>${opPreview.rows.map(r=>`<article class="review-card"><strong>${r.row}. ${ot(r.disposition)} · ${r.operation?esc(operationTitle(r.operation)):''}</strong>${r.error?`<p class="source-conflict">${esc(r.error)}</p>`:''}${r.existingStatus?`<p>${ot(r.existingStatus)}</p>`:''}${r.operation?operationDetail(r.operation):''}${opSuggestionList(r.suggestions)}${r.impact?`<p>${ot('impact')}: ${r.impact.references} / ${r.impact.relationships}</p>`:''}</article>`).join('')}<button id="operation-enqueue" ${!opPreview.valid||opBusy||!opState.canReview?'disabled':''}>${ot('enqueue')}</button><button id="operation-preview-cancel" ${opBusy?'disabled':''}>${ot('cancel')}</button></section>`:''}${opDecision?`<section class="undo-confirm"><h3>${ot(opDecision.action==='undo'?'undo':opDecision.action)}</h3><p>${esc(operationTitle(opDecision.row.operation))}</p>${operationDetail(opDecision.row.operation)}<label>${ot('reason')}<textarea id="operation-reason" maxlength="500">${esc(opNotes.get(opDecision.row.id)||'')}</textarea></label><button id="operation-confirm" ${opBusy?'disabled':''}>${ot('confirm')}</button><button id="operation-decision-cancel" ${opBusy?'disabled':''}>${ot('cancel')}</button></section>`:''}<div class="review-list">${rows.map(r=>`<article class="review-card"><h3>${ot(r.operation.kind)} · ${esc(operationTitle(r.operation))}</h3><p>${ot(r.status)}</p>${operationDetail(r.operation)}${opSuggestionList(r.suggestions)}${r.blocked?`<p class="source-conflict">${ot('blocked')}: ${esc(r.blocked)}</p>`:''}<div class="review-actions">${r.status==='pending'?`<button data-operation="${r.id}" data-operation-action="approve" ${!opState.canReview||opBusy||reviewBusy||r.blocked?'disabled':''}>${ot('approve')}</button><button data-operation="${r.id}" data-operation-action="reject" ${!opState.canReview||opBusy||reviewBusy?'disabled':''}>${ot('reject')}</button>`:r.canUndo?`<button data-operation="${r.id}" data-operation-action="undo" ${!opState.canReview||opBusy||reviewBusy?'disabled':''}>${ot('undo')}</button>`:''}</div></article>`).join('')||`<p>${ot('empty')}</p>`}</div><h3>${ot('history')}</h3><ul class="review-history">${opState.events.map(e=>`<li>${esc(e.created_at)} · ${ot(e.action==='undo'?'undo':e.action)}<p>${esc(e.note)}</p></li>`).join('')||`<li>${rt('nohistory')}</li>`}</ul>`;
 el.querySelector('#operation-refresh').onclick=()=>{opDecision=null;opPreview=opInput=null;opPreparing=false;loadOperations()};el.querySelector('#operation-filter').onchange=e=>{opFilter=e.target.value;renderOperations(container)};el.querySelector('#operation-kind').onchange=e=>{opKind=e.target.value;renderOperations(container)};
 el.querySelector('.operation-form').ontoggle=e=>opDraft.open=e.target.open;el.querySelector('#operation-draft-kind').onchange=e=>{opDraftKind=e.target.value;opDraft.open=true;opEpoch++;opPreparing=false;opPreview=opInput=null;renderOperations(container)};
 el.querySelectorAll('[data-op-input]').forEach(input=>input.oninput=()=>{opDraft[input.dataset.opInput]=input.type==='checkbox'?input.checked:input.value;if(input.dataset.opInput==='trackId'){const track=index.get(input.value),edition=index.get(track?.editionId);if(edition){opDraft.editionId=edition.id;opDraft.releaseId=edition.externalIds?.musicbrainzRelease||'';for(const key of ['editionId','releaseId'])el.querySelector(`[data-op-input="${key}"]`).value=opDraft[key]}}});
 el.querySelector('#operation-draft-preview').onclick=()=>{for(const input of el.querySelectorAll('[data-op-input]'))opDraft[input.dataset.opInput]=input.type==='checkbox'?input.checked:input.value;try{previewOperationInput({operations:[operationFromForm()]})}catch(e){opMessage=ot('error')+' · '+e.message;renderOperations(container)}};
 el.querySelector('#operation-upload').onchange=e=>previewOperationFile(e.target.files?.[0]);
 el.querySelectorAll('[data-operation-action]').forEach(b=>b.onclick=()=>{opDecision={row:opState.operations.find(r=>r.id===b.dataset.operation),action:b.dataset.operationAction,token:opState.graphToken,epoch:opState.epoch};renderOperations(container);$('#operation-reason')?.focus()});
 if($('#operation-reason'))$('#operation-reason').oninput=e=>opNotes.set(opDecision.row.id,e.target.value);
 if($('#operation-decision-cancel'))$('#operation-decision-cancel').onclick=()=>{opDecision=null;renderOperations(container)};
 if($('#operation-confirm'))$('#operation-confirm').onclick=async()=>{const d=opDecision,note=opNotes.get(d.row.id)||'';if(!note.trim()){opMessage=ot('reason');renderOperations(container);return}await operationRequest('/api/operations/'+d.row.id+(d.action==='undo'?'/undo':''),{decision:d.action,expectedVersion:d.row.version,expectedEpoch:d.epoch,graphToken:d.token,note})};
 if($('#operation-preview-cancel'))$('#operation-preview-cancel').onclick=()=>{opEpoch++;opPreparing=false;opPreview=opInput=null;opMessage='';renderOperations(container)};
 if($('#operation-enqueue'))$('#operation-enqueue').onclick=()=>operationRequest('/api/operations/import',opInput);
}
function operationFromForm(){const o={kind:opDraftKind,...Object.fromEntries(['sourceUrl','sourceType','checkedAt','note'].map(k=>[k,opDraft[k]||'']))};const parse=k=>JSON.parse(opDraft[k]||'{}');if(o.kind==='entity')o.node={...parse('context'),id:opDraft.id,type:opDraft.type,labels:Object.fromEntries(['zh','en','ja'].map(k=>[k,opDraft['labels_'+k]])),description:Object.fromEntries(['zh','en','ja'].map(k=>[k,opDraft['description_'+k]])),attributes:parse('attributes'),externalIds:parse('externalIds')};else if(o.kind==='relationship')o.relationship={source:opDraft.source,target:opDraft.target,type:opDraft.relation,attributes:parse('attributes')};else if(o.kind==='merge')Object.assign(o,{fromId:opDraft.fromId,intoId:opDraft.intoId,confirmSameIdentity:!!opDraft.same});else for(const k of ['trackId','editionId','recordingId','releaseId','matchBasis'])o[k]=opDraft[k];return o}
async function loadOperations(){if(opLoading||opBusy)return;opLoading=true;const epoch=++opEpoch;opMessage='';try{const r=await fetch('/api/operations',{cache:'no-store'});if(!r.ok)throw Error();const next=await r.json();if(!Array.isArray(next.operations)||!Array.isArray(next.events))throw Error();if(epoch===opEpoch)opState=next}catch{if(epoch===opEpoch)opMessage=ot('error')}finally{opLoading=false;if(view==='review')renderOperations($('#review'))}}
async function previewOperationFile(file){if(!file||opBusy)return;const epoch=++opEpoch;opPreview=opInput=null;opPreparing=true;opMessage=rt('loading');renderOperations($('#review'));try{if(file.size>65536)throw Error('body_too_large');const parsed=JSON.parse(await file.text());if(epoch!==opEpoch)return;await previewOperationInput({operations:Array.isArray(parsed)?parsed:parsed.operations})}catch(e){if(epoch===opEpoch){opPreparing=false;opMessage=ot('error')+' · '+e.message;renderOperations($('#review'))}}}
async function previewOperationInput(body){if(opBusy||!opState?.canReview)return;const epoch=++opEpoch;opPreview=opInput=null;opPreparing=true;opMessage=rt('loading');renderOperations($('#review'));try{const payload=JSON.stringify(body);if(new TextEncoder().encode(payload).length>65536)throw Error('body_too_large');const r=await fetch('/api/operations/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:payload});const result=await r.json();if(epoch!==opEpoch)return;if(!r.ok)throw Error(result.error);opPreview=result;opInput=body;opMessage=''}catch(e){if(epoch===opEpoch)opMessage=ot('error')+' · '+e.message}finally{if(epoch===opEpoch){opPreparing=false;renderOperations($('#review'));$('#operation-preview-title')?.focus()}}}
async function operationRequest(path,body){if(opBusy||reviewBusy||!opState?.canReview)return;opEpoch++;opPreparing=false;opBusy=true;let committed=false;renderOperations($('#review'));try{const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await r.json();if(!r.ok)throw Error(r.status===409?ot('stale'):result.error);committed=true;opDecision=null;opPreview=opInput=null;opMessage=ot('saved');await refreshArchive();const response=await fetch('/api/operations',{cache:'no-store'});if(!response.ok)throw Error();opState=await response.json();await loadReview()}catch(e){opMessage=(committed?rt('refreshNeeded'):ot('error'))+' · '+e.message}finally{opBusy=false;if(view==='review')renderOperations($('#review'))}}

render();

document.addEventListener('visibilitychange',()=>{if(document.hidden)stopRotation()});
